import { useState, useMemo } from 'react';import { Link } from 'react-router-dom';import {   Search,   Maximize2,   X,   Layers,   Eye,   Cpu,   Activity,   BatteryCharging,   Radio,   Anchor,   ArrowUpRight,  Terminal,  Grid,  ListFilter} from 'lucide-react';interface ComponentItem {  id: string;  partNo: string;  role: string;  emoji: string;  name: string;  category: 'perception' | 'compute' | 'propulsion' | 'sensors' | 'power' | 'structure';  categoryLabel: string;  subsystemTag: string;  blueprintZone: string;  description: string;  quote: string;  specs: { label: string; value: string }[];}export default function Technology() {  const [selectedCategory, setSelectedCategory] = useState<string>('all');  const [searchQuery, setSearchQuery] = useState<string>('');  const [activeComponentId, setActiveComponentId] = useState<string | null>(null);  const [isLightboxOpen, setIsLightboxOpen] = useState<boolean>(false);  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');  const componentsData: ComponentItem[] = useMemo(() => [    {      id: 'eye',      partNo: 'FS-01',      role: 'The Eye',      emoji: '👁️',      name: 'Seeed Studio XIAO ESP32-S3 Sense',      category: 'perception',      categoryLabel: 'Vision & Perception',      subsystemTag: 'SYS-VISION',      blueprintZone: '01 // PTZ CAMERA MAST',      description: 'The Seeed Studio XIAO ESP32-S3 Sense gives FloodScout its vision. Its built-in camera captures the environment around the robot, while the ESP32-S3 provides the processing capability needed for vision-based functions. Its compact size also allows us to fit powerful sensing capabilities into a small robotic platform.',      quote: 'Small in size, but responsible for giving FloodScout a view of the world.',      specs: [        { label: 'Processor', value: 'ESP32-S3 Dual-Core 240MHz' },        { label: 'Camera Sensor', value: 'OV2640 1600×1200 UXGA' },        { label: 'Dimensions', value: '21.0 × 17.5 mm' },        { label: 'Wireless', value: 'Wi-Fi 2.4GHz & BLE 5.0' },      ],    },    {      id: 'brain',      partNo: 'FS-02',      role: 'The Brain',      emoji: '🧠',      name: 'NodeMCU ESP32',      category: 'compute',      categoryLabel: 'Compute & Processing',      subsystemTag: 'SYS-COMPUTE',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: 'The NodeMCU ESP32 acts as one of the central controllers of FloodScout. It communicates with connected sensors and hardware, receives commands, and coordinates different functions of the robot. By dividing responsibilities between controllers, we can build the system in a more manageable and flexible way.',      quote: 'It connects the different parts of FloodScout and turns individual components into one system.',      specs: [        { label: 'Architecture', value: 'Xtensa 32-bit LX6' },        { label: 'Clock Speed', value: '240 MHz' },        { label: 'SRAM / Flash', value: '520 KB / 4 MB' },        { label: 'Interfaces', value: 'UART, I2C, SPI, PWM, ADC' },      ],    },    {      id: 'connector',      partNo: 'FS-03',      role: 'The Connector',      emoji: '🔌',      name: 'ESP32 30-Pin Expansion Board',      category: 'compute',      categoryLabel: 'Compute & Processing',      subsystemTag: 'SYS-COMPUTE',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The ESP32 30-Pin Expansion Board provides easier access to the NodeMCU's GPIO pins and power connections. This allows sensors, actuators, and other peripherals to be connected without dealing with the limited physical space of the development board itself. It also makes the prototype easier to wire, test, troubleshoot, and modify.",      quote: 'A simple interface that helps turn a development board into a complete robotic control system.',      specs: [        { label: 'Pin Count', value: '30-Pin Header Breakout' },        { label: 'Power Input', value: 'DC 6.5V - 16V Barrel / Term' },        { label: 'Rail Voltages', value: '5V & 3.3V Regulated Rails' },        { label: 'Terminal Style', value: 'Standard 2.54mm Pitch' },      ],    },    {      id: 'remote',      partNo: 'FS-04',      role: 'The Remote',      emoji: '🎮',      name: 'HotRC 6CH 2.4GHz Transmitter + Receiver',      category: 'compute',      categoryLabel: 'Wireless & Telemetry',      subsystemTag: 'SYS-COMMS',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: 'The HotRC 6-channel 2.4GHz transmitter and receiver provides the direct wireless control link between the operator and FloodScout. The transmitter sends commands while the receiver mounted on the robot receives them and passes them to the appropriate control system. This allows the operator to control the robot from a safer distance while FloodScout explores the water.',      quote: 'The hands stay with the operator while the robot takes the first step.',      specs: [        { label: 'Channels', value: '6 Proportional Channels' },        { label: 'Frequency Band', value: '2.400 - 2.4835 GHz FHSS' },        { label: 'Operating Range', value: 'Up to 400m Line-of-Sight' },        { label: 'Signal Output', value: 'Standard PWM Servo Signals' },      ],    },    {      id: 'muscle',      partNo: 'FS-05',      role: 'The Muscle',      emoji: '🛞',      name: '12–24V 20A BLDC Underwater Thruster',      category: 'propulsion',      categoryLabel: 'Propulsion & Drive',      subsystemTag: 'SYS-PROPULSION',      blueprintZone: '04 // UNDERSIDE THRUSTER PODS',      description: 'The 12–24V 20A BLDC underwater thruster provides the main propulsion force for FloodScout. Designed for underwater operation, it converts electrical energy into thrust and allows the robot to travel through the water. Its high-power design gives the compact platform the strength needed to carry its electronics and sensing equipment while moving.',      quote: 'The component that transforms FloodScout from a floating platform into a moving scout.',      specs: [        { label: 'Motor Type', value: 'Brushless DC (BLDC) 3-Phase' },        { label: 'Voltage Range', value: '12V – 24V DC (4S Compatible)' },        { label: 'Max Current', value: '20A Peak Sustained' },        { label: 'Ducting', value: 'High-Efficiency Weedless Duct' },      ],    },    {      id: 'driver',      partNo: 'FS-06',      role: 'The Driver',      emoji: '⚡',      name: 'Bidirectional Brushless ESC ≥30A',      category: 'propulsion',      categoryLabel: 'Propulsion & Drive',      subsystemTag: 'SYS-PROPULSION',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The bidirectional brushless ESC controls the power delivered from the battery to the BLDC underwater thruster. It regulates the motor's operation and supports both forward and reverse directions, allowing FloodScout to move according to the operator's commands. The ESC acts as the critical link between the robot's control system and its propulsion system.",      quote: 'It takes a command to move and turns it into controlled motor power.',      specs: [        { label: 'Continuous Current', value: '30A (Burst 40A)' },        { label: 'Control Direction', value: 'Full Bidirectional (Fwd/Rev)' },        { label: 'BEC Output', value: '5V / 2A Linear BEC' },        { label: 'Signal Protocol', value: 'PWM 1000–2000µs (1500 Neutral)' },      ],    },    {      id: 'joint',      partNo: 'FS-07',      role: 'The Joint',      emoji: '🦾',      name: 'SG90 Servo Motor',      category: 'perception',      categoryLabel: 'Vision & Perception',      subsystemTag: 'SYS-VISION',      blueprintZone: '01 // PTZ CAMERA MAST',      description: "The SG90 servo motor provides controlled rotational movement to the camera mechanism. Unlike a simple motor that continuously spins, the servo can move to specific positions, making it suitable for adjusting the camera's orientation. This gives FloodScout greater flexibility when observing its surroundings.",      quote: 'A small actuator that gives the robot the ability to change its perspective.',      specs: [        { label: 'Rotation Range', value: '180° Angular Range' },        { label: 'Operating Speed', value: '0.1s / 60 degrees' },        { label: 'Torque', value: '1.8 kg-cm @ 4.8V' },        { label: 'Weight', value: '9g Ultra-Lightweight' },      ],    },    {      id: 'neck',      partNo: 'FS-08',      role: 'The Neck',      emoji: '🔭',      name: 'PTZ Pan and Tilt Camera Bracket',      category: 'perception',      categoryLabel: 'Vision & Perception',      subsystemTag: 'SYS-VISION',      blueprintZone: '01 // PTZ CAMERA MAST',      description: "The PTZ pan-and-tilt camera bracket holds the camera and allows it to change its viewing direction. The mechanism can adjust the camera's horizontal and vertical position, giving FloodScout a broader field of view without requiring the entire robot to turn. This is especially useful when the robot needs to inspect different areas while remaining in position.",      quote: 'Instead of turning the whole body, FloodScout can simply turn its eyes.',      specs: [        { label: 'Axes of Freedom', value: '2-Axis (Pan & Tilt)' },        { label: 'Material', value: 'Injection Molded Nylon Resin' },        { label: 'Mounting Base', value: '4-Point Fastener Flange' },        { label: 'Payload Fit', value: 'XIAO ESP32-S3 Camera Module' },      ],    },    {      id: 'sense',      partNo: 'FS-09',      role: 'The Sense',      emoji: '📡',      name: 'Ultrasonic Sensor HC-SR04',      category: 'sensors',      categoryLabel: 'Sensors & Telemetry',      subsystemTag: 'SYS-SENSING',      blueprintZone: '03 // FRONT ACOUSTIC SONAR ARRAY',      description: 'The HC-SR04 ultrasonic sensor provides FloodScout with distance information about nearby objects. It sends ultrasonic waves and measures the returning echo to estimate the distance to an obstacle. This creates an additional sensing layer that works alongside the camera to improve the robot\'s awareness of its surroundings.',      quote: 'When the environment is difficult to see, FloodScout can use sound to sense what is ahead.',      specs: [        { label: 'Detection Range', value: '2 cm – 400 cm' },        { label: 'Accuracy', value: '±3 mm Precision' },        { label: 'Ultrasound Freq', value: '40 kHz Sound Pulses' },        { label: 'Trigger Signal', value: '10µs TTL Pulse' },      ],    },    {      id: 'navigator',      partNo: 'FS-10',      role: 'The Navigator',      emoji: '📍',      name: 'GY-NEO8M GPS',      category: 'sensors',      categoryLabel: 'Sensors & Telemetry',      subsystemTag: 'SYS-NAV',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The GY-NEO8M GPS module provides geographical positioning information when satellite signals are available. The location data can be used to track FloodScout's position and associate observations with a specific location. This becomes especially useful when the operator needs to understand not only what the robot has discovered, but where the discovery occurred.",      quote: 'It gives FloodScout a sense of place.',      specs: [        { label: 'Constellation', value: 'GPS / GLONASS / Galileo' },        { label: 'Baud Rate', value: '9600 bps UART Serial' },        { label: 'Position Accuracy', value: '2.5m CEP' },        { label: 'Antenna', value: '25×25mm Ceramic Patch' },      ],    },    {      id: 'heart',      partNo: 'FS-11',      role: 'The Heart',      emoji: '🔋',      name: '4S 14.8V 2200mAh 25C LiPo Battery',      category: 'power',      categoryLabel: 'Power Architecture',      subsystemTag: 'SYS-POWER',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The 4S 14.8V 2200mAh 25C LiPo battery is the primary energy source for FloodScout. It provides the electrical power required by the high-current propulsion system and other onboard electronics, with voltage regulation used for components that require lower voltages. Its capacity and discharge characteristics directly influence the robot's available operating time and power.",      quote: 'Every movement, sensor reading, and electronic function begins with the energy stored here.',      specs: [        { label: 'Nominal Voltage', value: '14.8V (4S1P Configuration)' },        { label: 'Capacity', value: '2200 mAh (32.56 Wh)' },        { label: 'Discharge Rate', value: '25C Continuous (55A)' },        { label: 'Weight', value: 'approx. 240g' },      ],    },    {      id: 'power-link',      partNo: 'FS-12',      role: 'The Power Link',      emoji: '🔗',      name: 'LiPo Battery Plug Male XT60',      category: 'power',      categoryLabel: 'Power Architecture',      subsystemTag: 'SYS-POWER',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The XT60 male battery plug provides a secure connection between the LiPo battery and the robot's main power circuit. It is designed for high-current applications and creates a firm electrical connection that can handle the demands of the propulsion system. Reliable power connections are essential when a single battery supplies multiple systems.",      quote: 'A small connection carrying the energy that keeps FloodScout alive.',      specs: [        { label: 'Continuous Rating', value: '60A Constant Load' },        { label: 'Contact Material', value: 'Gold-Plated Brass' },        { label: 'Housing', value: 'High-Temp Nylon (UL94 V-0)' },        { label: 'Polarity Protection', value: 'Keyed Asymmetric Shell' },      ],    },    {      id: 'distributor',      partNo: 'FS-13',      role: 'The Distributor',      emoji: '🔀',      name: 'XT60 Parallel Battery Connector',      category: 'power',      categoryLabel: 'Power Architecture',      subsystemTag: 'SYS-POWER',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The XT60 parallel battery connector allows the main battery connection to be distributed into multiple power paths. This provides a practical way to connect different parts of the robot's electrical system to the same power source. It helps organize the power architecture while maintaining the secure XT60 connection standard.",      quote: 'One source of energy, distributed across the systems that need it.',      specs: [        { label: 'Topology', value: '1-to-2 Parallel Splitter' },        { label: 'Connector Standard', value: 'Authentic XT60 Interface' },        { label: 'Max Voltage', value: '500V DC Insulation' },        { label: 'Application', value: 'Dual ESC & Logic Bus Feed' },      ],    },    {      id: 'power-cable',      partNo: 'FS-14',      role: 'The Power Cable',      emoji: '💪',      name: 'AWG12 Silicone Flexible Multicore Wire',      category: 'power',      categoryLabel: 'Power Architecture',      subsystemTag: 'SYS-POWER',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The AWG12 silicone wire is used for higher-current connections within FloodScout's power and propulsion circuits. Its larger conductor is suited to carrying the substantial current required by high-power components, while the flexible silicone insulation makes it easier to route through the compact body. Proper wire selection is important for both electrical performance and safety.",      quote: "Built to carry the power behind FloodScout's movement.",      specs: [        { label: 'Conductor Gauge', value: 'AWG 12 (3.31 mm²)' },        { label: 'Strand Count', value: '680 Tinned Copper Strands' },        { label: 'Temp Range', value: '-60°C to +200°C' },        { label: 'Max Current', value: '88.4A Short Burst' },      ],    },    {      id: 'signal-wire',      partNo: 'FS-15',      role: 'The Signal Wire',      emoji: '🧵',      name: '22 AWG Wire',      category: 'power',      categoryLabel: 'Power Architecture',      subsystemTag: 'SYS-POWER',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The 22 AWG wire is used for lower-current electrical connections, particularly for signals and control between different components. Its smaller size helps reduce clutter within the robot and makes it easier to organize the many connections required by the sensors and controllers.",      quote: 'Not every wire carries power — some carry the information that makes the robot respond.',      specs: [        { label: 'Conductor Gauge', value: 'AWG 22 (0.33 mm²)' },        { label: 'Usage', value: 'PWM, I2C, UART Signals' },        { label: 'Insulation', value: 'Flexible PVC / Silicone' },        { label: 'Current Rating', value: '7A Continuous Max' },      ],    },    {      id: 'quick-link',      partNo: 'FS-16',      role: 'The Quick Link',      emoji: '🪢',      name: 'Jumper Wire',      category: 'power',      categoryLabel: 'Power Architecture',      subsystemTag: 'SYS-POWER',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: 'Jumper wires provide temporary and flexible connections between development boards, sensors, and other electronic components. They are particularly useful during the prototyping stage because connections can be changed quickly while testing different configurations. This flexibility allows us to experiment and iterate without rebuilding the entire circuit.',      quote: 'Before a design becomes permanent, jumper wires help us discover what works.',      specs: [        { label: 'Terminations', value: 'Male-to-Female / M-M / F-F' },        { label: 'Header Pitch', value: 'Standard 2.54 mm' },        { label: 'Conductor', value: 'Multi-Core Copper' },        { label: 'Purpose', value: 'Modular Prototyping Link' },      ],    },    {      id: 'protector',      partNo: 'FS-17',      role: 'The Protector',      emoji: '🛡️',      name: 'Heat Shrink Tube',      category: 'structure',      categoryLabel: 'Protection & Enclosure',      subsystemTag: 'SYS-PROTECT',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: 'Heat shrink tubing protects exposed electrical connections by creating an insulated layer around wires and terminals. When heated, the tubing contracts tightly around the connection, helping reduce the risk of short circuits and providing additional mechanical protection. It may be a small component, but it contributes to the reliability of the entire electrical system.',      quote: 'Sometimes the smallest layer of protection makes the biggest difference.',      specs: [        { label: 'Shrink Ratio', value: '2:1 Thermal Contraction' },        { label: 'Dielectric Strength', value: '600V Insulation' },        { label: 'Shrink Temperature', value: '70°C – 125°C' },        { label: 'Material', value: 'Cross-Linked Polyolefin' },      ],    },    {      id: 'guardian',      partNo: 'FS-18',      role: 'The Guardian',      emoji: '🚨',      name: 'Fuse Box and Blade Fuse',      category: 'structure',      categoryLabel: 'Protection & Enclosure',      subsystemTag: 'SYS-PROTECT',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The fuse box and blade fuse provide an additional layer of protection for FloodScout's electrical system. If excessive current flows through the circuit, the fuse is designed to break the connection and help protect the wiring and connected components. This is especially important in a high-current system powered by a LiPo battery.",      quote: "FloodScout is built to explore the water — but its electrical system needs protection while doing so.",      specs: [        { label: 'Fuse Standard', value: 'Standard Automotive Blade' },        { label: 'Current Rating', value: '25A / 30A Fast Blow' },        { label: 'Housing Spec', value: 'Splash-Resistant Rubber Seal' },        { label: 'Circuit Impact', value: 'Overcurrent Fail-Safe' },      ],    },    {      id: 'regulator',      partNo: 'FS-19',      role: 'The Regulator',      emoji: '🔽',      name: 'LM2596 Step-Down Converter',      category: 'power',      categoryLabel: 'Power Architecture',      subsystemTag: 'SYS-POWER',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: 'The LM2596 adjustable step-down regulator manages voltage between the main battery and compatible lower-voltage electronics. Since different components have different voltage requirements, the regulator converts the higher battery voltage to a suitable lower output. Its adjustable design allows the power supply to be configured according to the needs of the connected electronics.',      quote: 'One battery provides the energy; the regulator makes that energy usable for different systems.',      specs: [        { label: 'Input Voltage', value: '4.5V – 40V DC' },        { label: 'Output Voltage', value: 'Adjustable 1.25V – 37V (Set to 5V)' },        { label: 'Max Output Current', value: '3A Peak Output' },        { label: 'Conversion Eff.', value: 'Up to 92% Efficiency' },      ],    },    {      id: 'shelter',      partNo: 'FS-20',      role: 'The Shelter',      emoji: '🏠',      name: 'Electronic Plastic Box',      category: 'structure',      categoryLabel: 'Protection & Enclosure',      subsystemTag: 'SYS-STRUCTURE',      blueprintZone: '02 // ELECTRONICS SHELTER',      description: "The 320 × 240 × 110 mm electronic plastic box houses FloodScout's sensitive electronics and helps organize the internal system. It provides space for the controllers, power-management components, wiring, and other electronic hardware while creating a physical barrier between the electronics and the surrounding environment. Its removable enclosure also makes maintenance and testing easier during development.",      quote: "Behind FloodScout's simple exterior is a protected space where its electronic systems come together.",      specs: [        { label: 'Dimensions', value: '320 × 240 × 110 mm' },        { label: 'Material', value: 'High-Impact Weatherproof ABS' },        { label: 'Fasteners', value: '4× Stainless Steel Top Screws' },        { label: 'Internal Space', value: 'Spacious Multi-Tier Layout' },      ],    },    {      id: 'foundation',      partNo: 'FS-21',      role: 'The Foundation',      emoji: '🛡️',      name: 'UPVC End Cap',      category: 'structure',      categoryLabel: 'Structure & Hull',      subsystemTag: 'SYS-HULL',      blueprintZone: '05 // TWIN BUOYANCY PONTOONS',      description: "The 82mm UPVC end cap contributes to the physical construction of FloodScout's body. UPVC is lightweight, water-resistant, and relatively easy to work with, making it a practical material for developing a water-based prototype. Rather than relying on expensive custom manufacturing, readily available materials allow us to build, test, and improve the design quickly.",      quote: 'A simple material helping us turn an idea into something that can actually enter the water.',      specs: [        { label: 'Diameter', value: '82 mm Caliber' },        { label: 'Material', value: 'Unplasticized Polyvinyl Chloride' },        { label: 'Seal Type', value: 'Solvent Weld Waterproof Joint' },        { label: 'Hydrodynamics', value: 'Hemispherical Bow/Stern Cap' },      ],    },    {      id: 'hull',      partNo: 'FS-22',      role: 'The Hull',      emoji: '🌊',      name: 'White PVC Pipe',      category: 'structure',      categoryLabel: 'Structure & Hull',      subsystemTag: 'SYS-HULL',      blueprintZone: '05 // TWIN BUOYANCY PONTOONS',      description: "The white PVC pipe forms part of FloodScout's floating structure and contributes to its overall buoyancy and physical stability. Its lightweight and water-resistant properties make it suitable for constructing a prototype designed to operate on water. Together with the other structural components, it provides the foundation that allows the electronics and propulsion system to stay above the waterline.",      quote: 'Before FloodScout can explore the flood, its body has one fundamental job — stay afloat.',      specs: [        { label: 'Displacement', value: 'Twin Hull Catamaran Floats' },        { label: 'Buoyancy Margin', value: '> 8.5 kg Reserve Buoyancy' },        { label: 'Wall Thickness', value: '3.2 mm Heavy Duty Schedule' },        { label: 'Stability Index', value: 'Dual-Outrigger Anti-Roll' },      ],    },  ], []);  const categories = [    { key: 'all', label: 'ALL COMPONENTS', count: 22, icon: Layers },    { key: 'perception', label: 'VISION & PTZ', count: 3, icon: Eye },    { key: 'compute', label: 'BRAIN & WIRELESS', count: 3, icon: Cpu },    { key: 'propulsion', label: 'PROPULSION & MOTOR', count: 2, icon: Activity },    { key: 'sensors', label: 'SENSORS & NAV', count: 2, icon: Radio },    { key: 'power', label: 'POWER & ELECTRICAL', count: 7, icon: BatteryCharging },    { key: 'structure', label: 'CHASSIS & HULL', count: 5, icon: Anchor },  ];  const filteredComponents = useMemo(() => {    return componentsData.filter(item => {      const matchesCategory = selectedCategory === 'all' || item.category === selectedCategory;      const query = searchQuery.toLowerCase().trim();      const matchesSearch =         !query ||        item.name.toLowerCase().includes(query) ||        item.role.toLowerCase().includes(query) ||        item.description.toLowerCase().includes(query) ||        item.quote.toLowerCase().includes(query) ||        item.partNo.toLowerCase().includes(query) ||        item.categoryLabel.toLowerCase().includes(query);      return matchesCategory && matchesSearch;    });  }, [componentsData, selectedCategory, searchQuery]);  const scrollToComponent = (id: string) => {    setActiveComponentId(id);    const el = document.getElementById(`part-${id}`);    if (el) {      el.scrollIntoView({ behavior: 'smooth', block: 'center' });    }  };  return (    <div className="w-full bg-[#ECECED] text-[#11141D] min-h-screen relative font-sans selection:bg-[#11141D] selection:text-[#FAF7F2] pb-24 overflow-x-hidden">            {/* Precision Drafting Grid Overlay */}      <div         className="fixed inset-0 pointer-events-none opacity-[0.45] z-0"        style={{          backgroundImage: `            linear-gradient(to right, rgba(17, 20, 29, 0.06) 1px, transparent 1px),            linear-gradient(to bottom, rgba(17, 20, 29, 0.06) 1px, transparent 1px)          `,          backgroundSize: '40px 40px',        }}      />      {/* ─── HERO SECTION: Project-Specific FloodScout Intro ─── */}      <section className="relative z-10 pt-10 sm:pt-14 md:pt-16 pb-12 px-5 sm:px-8 md:px-12 max-w-[1400px] mx-auto border-b border-[#D2D5DC]">        {/* Top CAD Drafting Header Strip */}        <div className="flex flex-wrap items-center justify-between gap-4 pb-6 mb-8 border-b border-[#D2D5DC] font-mono text-[10px] sm:text-[11px] tracking-[0.25em] text-[#555E6D] uppercase">          <div className="flex items-center gap-3">            <span className="w-2.5 h-2.5 bg-[#11141D] inline-block"></span>            <span>SYSTEM SPECIFICATION // REV 2.4</span>            <span className="hidden sm:inline text-[#9DA4B0]">|</span>            <span className="hidden sm:inline">AUTONOMOUS SURFACE VEHICLE (USV)</span>          </div>          <div className="flex items-center gap-4">            <span>DWG: UTM-FS-EXP-02</span>            <span className="text-[#9DA4B0]">•</span>            <span className="bg-[#11141D] text-[#ECECED] px-2 py-0.5 font-bold tracking-widest text-[9px]">VERIFIED PROTOTYPE</span>          </div>        </div>        {/* 2-Column Hero: Left Project Info / Right Exploded Blueprint */}        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 lg:gap-14 items-start">          {/* Left: Project Overview */}          <div className="lg:col-span-5 flex flex-col gap-6">            {/* Kicker */}            <div className="font-mono text-[11px] font-semibold tracking-[0.3em] text-[#555E6D] uppercase flex items-center gap-2">              <span className="inline-block w-4 h-[1px] bg-[#555E6D]"></span>              TOPIC // HARDWARE INTEGRATION            </div>            {/* Headline */}            <h1 className="text-4xl sm:text-6xl xl:text-7xl font-black tracking-tight text-[#11141D] uppercase leading-[0.92]">              EVERY PART<br />HAS A ROLE            </h1>            {/* Lead */}            <p className="text-sm sm:text-base text-[#384152] leading-relaxed">              FloodScout is built from carefully integrated components, each contributing to the robot&apos;s ability to see, sense, move, navigate, communicate, and stay protected. Explore the robot to discover what is happening beneath its surface.            </p>            {/* Metrics Grid — Project-Specific */}            <div className="grid grid-cols-3 gap-4 py-6 border-t border-b border-[#D2D5DC] font-mono">              <div>                <div className="text-[10px] tracking-[0.2em] text-[#717B8C] uppercase mb-1">PLATFORM</div>                <div className="text-xl sm:text-2xl font-light text-[#11141D] tracking-tight">CATAMARAN</div>              </div>              <div>                <div className="text-[10px] tracking-[0.2em] text-[#717B8C] uppercase mb-1">SUBSYSTEMS</div>                <div className="text-xl sm:text-2xl font-light text-[#11141D] tracking-tight">22 UNITS</div>              </div>              <div>                <div className="text-[10px] tracking-[0.2em] text-[#717B8C] uppercase mb-1">CONTROLLERS</div>                <div className="text-xl sm:text-2xl font-light text-[#11141D] tracking-tight">2 ESP32s</div>              </div>            </div>            {/* 4 Project Subsystem Pillars */}            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="flex items-center justify-between font-mono text-[10px] text-[#717B8C] mb-2">                  <span>01 // VISION</span>                  <Eye size={14} className="text-[#11141D]" />                </div>                <p className="text-xs text-[#384152] leading-relaxed">                  The Seeed Studio XIAO ESP32-S3 Sense delivers real-time camera footage, mounted on a 2-axis SG90 PTZ bracket so FloodScout can survey wide angles without repositioning.                </p>                <div className="mt-3 pt-2 border-t border-[#E4E6EA] font-mono text-[10px] text-[#717B8C] flex justify-between">                  <span>Eye • Neck • Joint</span>                  <span className="font-semibold text-black">OV2640</span>                </div>              </div>              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="flex items-center justify-between font-mono text-[10px] text-[#717B8C] mb-2">                  <span>02 // COMPUTE</span>                  <Cpu size={14} className="text-[#11141D]" />                </div>                <p className="text-xs text-[#384152] leading-relaxed">                  The NodeMCU ESP32 acts as the central controller, coordinating incoming HotRC 2.4GHz commands and dispatching PWM signals to thruster ESCs and GPS polling.                </p>                <div className="mt-3 pt-2 border-t border-[#E4E6EA] font-mono text-[10px] text-[#717B8C] flex justify-between">                  <span>Brain • Connector • Remote</span>                  <span className="font-semibold text-black">240MHz</span>                </div>              </div>              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="flex items-center justify-between font-mono text-[10px] text-[#717B8C] mb-2">                  <span>03 // PROPULSION</span>                  <Activity size={14} className="text-[#11141D]" />                </div>                <p className="text-xs text-[#384152] leading-relaxed">                  Twin BLDC underwater thrusters driven by bidirectional 30A ESCs provide forward and reverse thrust, allowing FloodScout to navigate flood currents.                </p>                <div className="mt-3 pt-2 border-t border-[#E4E6EA] font-mono text-[10px] text-[#717B8C] flex justify-between">                  <span>Muscle • Driver</span>                  <span className="font-semibold text-black">12–24V</span>                </div>              </div>              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="flex items-center justify-between font-mono text-[10px] text-[#717B8C] mb-2">                  <span>04 // POWER</span>                  <BatteryCharging size={14} className="text-[#11141D]" />                </div>                <p className="text-xs text-[#384152] leading-relaxed">                  A 4S 14.8V LiPo battery supplies the main bus through XT60 connectors and blade fuses, with an LM2596 step-down converter providing regulated 5V logic power.                </p>                <div className="mt-3 pt-2 border-t border-[#E4E6EA] font-mono text-[10px] text-[#717B8C] flex justify-between">                  <span>Heart • Guardian • Regulator</span>                  <span className="font-semibold text-black">14.8V</span>                </div>              </div>            </div>          </div>          {/* Right: Exploded Blueprint CAD Drawing */}          <div className="lg:col-span-7 flex flex-col items-center">            <div className="relative w-full border border-[#CBD0D9] bg-[#F5F5F7] p-4 sm:p-6 shadow-sm overflow-hidden group">              {/* CAD Corner Marks */}              <div className="absolute top-2 left-2 font-mono text-[11px] text-[#8C94A4] select-none">+</div>              <div className="absolute top-2 right-2 font-mono text-[11px] text-[#8C94A4] select-none">+</div>              <div className="absolute bottom-2 left-2 font-mono text-[11px] text-[#8C94A4] select-none">+</div>              <div className="absolute bottom-2 right-2 font-mono text-[11px] text-[#8C94A4] select-none">+</div>              {/* Drawing Title */}              <div className="flex items-center justify-between font-mono text-[10px] text-[#717B8C] tracking-[0.2em] uppercase border-b border-[#CBD0D9] pb-3 mb-4">                <span>FIG. 01 — EXPLODED ASSEMBLY VIEW</span>                <span className="hidden sm:inline">SCALE: 1:5 METRIC [mm]</span>              </div>              {/* FloodScout Blueprint Diagram */}              <div className="relative w-full aspect-[4/3] flex items-center justify-center overflow-hidden bg-white/60 border border-[#E0E2E7]">                <img                  src="/image/floodscout-exploded.jpg"                  alt="FloodScout Exploded Engineering CAD Line Drawing"                  className="w-full h-full object-contain mix-blend-multiply transition-transform duration-700 group-hover:scale-[1.02]"                />                {/* Hotspot Callouts */}                <button onClick={() => scrollToComponent('eye')}                  className="absolute top-[8%] left-[45%] -translate-x-1/2 bg-[#11141D] text-[#ECECED] text-[9px] font-mono font-bold tracking-wider px-2 py-0.5 rounded shadow-sm hover:scale-110 hover:bg-black transition-transform cursor-pointer border border-[#ECECED]">                  01 // PTZ VISION                </button>                <button onClick={() => scrollToComponent('shelter')}                  className="absolute top-[38%] left-[70%] -translate-x-1/2 bg-[#11141D] text-[#ECECED] text-[9px] font-mono font-bold tracking-wider px-2 py-0.5 rounded shadow-sm hover:scale-110 hover:bg-black transition-transform cursor-pointer border border-[#ECECED]">                  02 // ELECTRONICS                </button>                <button onClick={() => scrollToComponent('sense')}                  className="absolute top-[52%] left-[44%] -translate-x-1/2 bg-[#11141D] text-[#ECECED] text-[9px] font-mono font-bold tracking-wider px-2 py-0.5 rounded shadow-sm hover:scale-110 hover:bg-black transition-transform cursor-pointer border border-[#ECECED]">                  03 // SONAR                </button>                <button onClick={() => scrollToComponent('muscle')}                  className="absolute bottom-[20%] left-[54%] -translate-x-1/2 bg-[#11141D] text-[#ECECED] text-[9px] font-mono font-bold tracking-wider px-2 py-0.5 rounded shadow-sm hover:scale-110 hover:bg-black transition-transform cursor-pointer border border-[#ECECED]">                  04 // THRUSTERS                </button>                <button onClick={() => scrollToComponent('hull')}                  className="absolute bottom-[24%] left-[16%] -translate-x-1/2 bg-[#11141D] text-[#ECECED] text-[9px] font-mono font-bold tracking-wider px-2 py-0.5 rounded shadow-sm hover:scale-110 hover:bg-black transition-transform cursor-pointer border border-[#ECECED]">                  05 // PONTOONS                </button>                {/* Fullscreen Button */}                <button                  onClick={() => setIsLightboxOpen(true)}                  className="absolute bottom-3 right-3 bg-[#11141D]/90 hover:bg-[#11141D] text-white p-2 rounded-full transition-all shadow-md flex items-center gap-1.5 text-[10px] font-mono tracking-wider cursor-pointer"                >                  <Maximize2 size={13} />                  <span className="hidden sm:inline pr-1">FULLSCREEN</span>                </button>              </div>              {/* Key Strip */}              <div className="grid grid-cols-2 sm:grid-cols-5 gap-2 mt-4 pt-3 border-t border-[#CBD0D9] font-mono text-[9px] text-[#555E6D] uppercase">                <button onClick={() => scrollToComponent('eye')} className="text-left hover:text-black hover:font-bold transition-colors cursor-pointer">                  <span className="font-bold text-black">[01]</span> VISION HEAD                </button>                <button onClick={() => scrollToComponent('shelter')} className="text-left hover:text-black hover:font-bold transition-colors cursor-pointer">                  <span className="font-bold text-black">[02]</span> IP HOUSING                </button>                <button onClick={() => scrollToComponent('sense')} className="text-left hover:text-black hover:font-bold transition-colors cursor-pointer">                  <span className="font-bold text-black">[03]</span> SONAR SENSOR                </button>                <button onClick={() => scrollToComponent('muscle')} className="text-left hover:text-black hover:font-bold transition-colors cursor-pointer">                  <span className="font-bold text-black">[04]</span> PROPULSION                </button>                <button onClick={() => scrollToComponent('hull')} className="text-left hover:text-black hover:font-bold transition-colors cursor-pointer col-span-2 sm:col-span-1">                  <span className="font-bold text-black">[05]</span> PVC PONTOONS                </button>              </div>            </div>            {/* Dimensional specs footnote */}            <div className="w-full flex flex-wrap items-center justify-between gap-4 mt-3 px-1 font-mono text-[10px] text-[#717B8C]">              <span>BEAM: 480 MM</span>              <span>DRAFT: 150 MM</span>              <span>DISPLACEMENT: 11.2 KG MAX</span>            </div>          </div>        </div>      </section>      {/* ─── INTERACTIVE COMPONENT DIRECTORY ("Every Part Has a Role") ─── */}      <section className="relative z-10 pt-14 px-5 sm:px-8 md:px-12 max-w-[1400px] mx-auto" id="hardware-roster">                {/* Section Header */}        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 pb-8 border-b border-[#CBD0D9]">          <div>            <div className="font-mono text-[10px] sm:text-[11px] tracking-[0.25em] text-[#717B8C] uppercase mb-1">              SUBSYSTEM DIRECTORY // 22 INTEGRATED COMPONENTS            </div>            <h2 className="text-3xl sm:text-4xl md:text-5xl font-black uppercase tracking-tight text-[#11141D]">              Complete Component Roster            </h2>          </div>          {/* View Mode Toggle */}          <div className="flex items-center gap-2 font-mono text-xs self-start md:self-auto">            <span className="text-[#717B8C] text-[10px] uppercase tracking-wider mr-1">VIEW:</span>            <button              onClick={() => setViewMode('grid')}              className={`flex items-center gap-1.5 px-3 py-1.5 border ${                viewMode === 'grid'                   ? 'bg-[#11141D] text-white border-[#11141D]'                   : 'bg-white text-[#555E6D] border-[#CBD0D9] hover:text-black'              } transition-colors cursor-pointer text-[11px]`}            >              <Grid size={13} />              GRID            </button>            <button              onClick={() => setViewMode('table')}              className={`flex items-center gap-1.5 px-3 py-1.5 border ${                viewMode === 'table'                   ? 'bg-[#11141D] text-white border-[#11141D]'                   : 'bg-white text-[#555E6D] border-[#CBD0D9] hover:text-black'              } transition-colors cursor-pointer text-[11px]`}            >              <ListFilter size={13} />              TABLE            </button>          </div>        </div>        {/* Filter Controls Bar: Search & Subsystem Pills */}        <div className="py-6 flex flex-col lg:flex-row lg:items-center justify-between gap-4 border-b border-[#CBD0D9]">                    {/* Subsystem Category Pills */}          <div className="flex flex-wrap items-center gap-2">            {categories.map((cat) => {              const Icon = cat.icon;              const isSelected = selectedCategory === cat.key;              return (                <button                  key={cat.key}                  onClick={() => setSelectedCategory(cat.key)}                  className={`flex items-center gap-2 px-3 py-1.5 font-mono text-[10px] sm:text-[11px] tracking-wider uppercase transition-all border cursor-pointer ${                    isSelected                       ? 'bg-[#11141D] text-white border-[#11141D] font-bold shadow-sm'                       : 'bg-white/80 text-[#555E6D] border-[#CBD0D9] hover:border-black hover:text-black'                  }`}                >                  <Icon size={12} />                  <span>{cat.label}</span>                  <span className={`px-1.5 py-0.2 rounded-full text-[9px] ${isSelected ? 'bg-white/20 text-white' : 'bg-[#E0E2E7] text-[#555E6D]'}`}>                    {cat.count}                  </span>                </button>              );            })}          </div>          {/* Search Input Bar */}          <div className="relative min-w-[260px] sm:w-80">            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#717B8C]" />            <input              type="text"              value={searchQuery}              onChange={(e) => setSearchQuery(e.target.value)}              placeholder="Search components or roles..."              className="w-full bg-white border border-[#CBD0D9] text-[#11141D] placeholder-[#8C94A4] pl-9 pr-8 py-2 text-xs font-mono focus:outline-none focus:border-black focus:ring-1 focus:ring-black"            />            {searchQuery && (              <button                 onClick={() => setSearchQuery('')}                className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[#717B8C] hover:text-black"              >                <X size={14} />              </button>            )}          </div>        </div>        {/* Results Counter */}        <div className="py-3 flex items-center justify-between font-mono text-[10px] text-[#717B8C] uppercase">          <span>SHOWING {filteredComponents.length} OF 22 HARDWARE COMPONENTS</span>          {searchQuery && (            <span>FILTERED BY: "{searchQuery}"</span>          )}        </div>        {/* ─── GRID VIEW: Technical Blueprint Spec Cards ─── */}        {viewMode === 'grid' && (          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 pt-4">            {filteredComponents.map((item) => {              const isHighlighted = activeComponentId === item.id;              return (                <div                  key={item.id}                  id={`part-${item.id}`}                  className={`border bg-white transition-all duration-300 flex flex-col justify-between relative group ${                    isHighlighted                       ? 'border-[#11141D] ring-2 ring-[#11141D] shadow-lg bg-[#FAF7F2]'                       : 'border-[#CBD0D9] hover:border-black hover:shadow-md'                  }`}                >                  {/* Card CAD Border Header */}                  <div className="border-b border-[#E4E6EA]">                    {/* Component Product Image */}                    <div className="w-full aspect-[4/3] bg-[#F8F9FA] overflow-hidden border-b border-[#E4E6EA]">                      <img                        src={`/image/components/${item.id}.jpg`}                        alt={item.name}                        className="w-full h-full object-contain p-3 mix-blend-multiply transition-transform duration-500 group-hover:scale-[1.04]"                        onError={(e) => {                          (e.currentTarget as HTMLImageElement).style.display = 'none';                        }}                      />                    </div>                    <div className="p-5 pb-4">                      {/* Top Row: Part ID, Category Tag, Zone */}                      <div className="flex items-center justify-between font-mono text-[10px] text-[#717B8C] uppercase tracking-wider mb-2.5">                        <div className="flex items-center gap-2">                          <span className="bg-[#11141D] text-white px-1.5 py-0.5 font-bold">                            {item.partNo}                          </span>                          <span className="font-semibold text-black">                            {item.subsystemTag}                          </span>                        </div>                        <span className="text-[9px] text-[#8C94A4] truncate max-w-[140px]">                          {item.blueprintZone}                        </span>                      </div>                      {/* Role Title with Emoji */}                      <div className="flex items-center gap-2.5 mb-1.5">                        <span className="text-xl sm:text-2xl select-none" role="img" aria-label={item.role}>                          {item.emoji}                        </span>                        <h3 className="text-lg sm:text-xl font-black uppercase tracking-tight text-[#11141D]">                          {item.role}                        </h3>                      </div>                      {/* Official Hardware Component Name */}                      <h4 className="font-mono text-xs font-semibold text-[#384152] leading-snug">                        {item.name}                      </h4>                    </div>                  </div>                  {/* Body: Detailed Description & Exact Philosophy Quote */}                  <div className="p-5 flex-1 flex flex-col justify-between">                                        {/* Technical Rationale Description */}                    <p className="text-xs sm:text-[13px] text-[#4A5568] leading-relaxed mb-5 font-normal">                      {item.description}                    </p>                    {/* Highlighted Exact Quote Callout */}                    <div className="border-l-2 border-[#11141D] bg-[#F4F5F7] p-3 rounded-none mb-5">                      <span className="text-[9px] font-mono tracking-widest text-[#717B8C] uppercase block mb-1">                        ENGINEERING PHILOSOPHY                      </span>                      <p className="text-xs text-[#11141D] font-serif italic leading-relaxed">                        "{item.quote}"                      </p>                    </div>                    {/* Micro Specs List */}                    <div className="space-y-1.5 pt-3 border-t border-[#EAECEF] font-mono text-[10px]">                      {item.specs.map((spec, i) => (                        <div key={i} className="flex items-center justify-between text-[#555E6D]">                          <span className="text-[#8C94A4] uppercase">{spec.label}</span>                          <span className="font-medium text-[#11141D] text-right">{spec.value}</span>                        </div>                      ))}                    </div>                  </div>                  {/* Card Footer: Blueprint Link */}                  <div className="px-5 py-2.5 bg-[#F8F9FA] border-t border-[#E4E6EA] flex items-center justify-between font-mono text-[10px] text-[#717B8C]">                    <span>STATUS: MOUNTED</span>                    <button                      onClick={() => {                        window.scrollTo({ top: 0, behavior: 'smooth' });                      }}                      className="hover:text-black flex items-center gap-1 uppercase tracking-wider font-semibold cursor-pointer"                    >                      VIEW ON BLUEPRINT                      <ArrowUpRight size={11} />                    </button>                  </div>                </div>              );            })}          </div>        )}        {/* ─── TABLE VIEW: Aerospace Telemetry Roster ─── */}        {viewMode === 'table' && (          <div className="overflow-x-auto border border-[#CBD0D9] bg-white mt-4">            <table className="w-full text-left font-mono text-xs">              <thead className="bg-[#11141D] text-[#ECECED] uppercase text-[10px] tracking-wider border-b border-black">                <tr>                  <th className="py-3 px-4">PART NO</th>                  <th className="py-3 px-4">ROLE</th>                  <th className="py-3 px-4">COMPONENT HARDWARE</th>                  <th className="py-3 px-4">SUBSYSTEM</th>                  <th className="py-3 px-4">ASSEMBLY ZONE</th>                  <th className="py-3 px-4">KEY ROLE SUMMARY</th>                </tr>              </thead>              <tbody className="divide-y divide-[#E4E6EA]">                {filteredComponents.map((item) => (                  <tr                     key={item.id}                    id={`part-${item.id}`}                    className="hover:bg-[#F4F5F7] transition-colors cursor-pointer"                    onClick={() => setActiveComponentId(item.id)}                  >                    <td className="py-3 px-4 font-bold text-black whitespace-nowrap">                      {item.partNo}                    </td>                    <td className="py-3 px-4 whitespace-nowrap font-sans font-bold text-sm text-black">                      <span className="mr-1.5">{item.emoji}</span>                      {item.role}                    </td>                    <td className="py-3 px-4 font-semibold text-[#11141D]">                      {item.name}                    </td>                    <td className="py-3 px-4 text-[#555E6D] text-[11px] whitespace-nowrap">                      {item.categoryLabel}                    </td>                    <td className="py-3 px-4 text-[#717B8C] text-[10px] whitespace-nowrap">                      {item.blueprintZone}                    </td>                    <td className="py-3 px-4 text-[#384152] italic font-serif text-[11px] max-w-md">                      "{item.quote}"                    </td>                  </tr>                ))}              </tbody>            </table>          </div>        )}      </section>      {/* ─── TECHNICAL BENCHMARKS & OPERATIONAL CAPACITY ─── */}      <section className="relative z-10 py-16 px-5 sm:px-8 md:px-12 max-w-[1400px] mx-auto border-t border-[#D2D5DC] mt-16">        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 items-center">                    <div className="lg:col-span-5">            <span className="font-mono text-[10px] tracking-[0.25em] text-[#717B8C] uppercase block mb-1">              FIELD BENCHMARKS // OPERATIONAL METRICS            </span>            <h2 className="text-3xl sm:text-4xl font-black uppercase tracking-tight text-[#11141D] mb-4">              Waterborne Readiness &amp; Deployment Limits            </h2>            <p className="text-xs sm:text-sm text-[#4A5568] leading-relaxed mb-6">              Tested under realistic urban and rural flash flood conditions. The catamaran hull provides exceptional roll resistance in 1.8 m/s current velocities, while maintaining uninterrupted video transmission to rescue teams on shore.            </p>            <div className="flex flex-wrap gap-4">              <Link                to="/dashboard"                className="bg-[#11141D] text-white hover:bg-black px-6 py-3 font-mono text-xs font-bold tracking-[0.2em] uppercase transition-all shadow-sm flex items-center gap-2"              >                <Terminal size={14} />                LAUNCH LIVE DASHBOARD              </Link>            </div>          </div>          <div className="lg:col-span-7">            <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 font-mono">                            <div className="border border-[#CBD0D9] bg-white p-4">                <div className="text-[10px] text-[#717B8C] uppercase mb-1">MAX OPERATING TIME</div>                <div className="text-2xl font-light text-black">4.2 HOURS</div>                <div className="text-[9px] text-[#8C94A4] mt-1">Under nominal scout cruise</div>              </div>              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="text-[10px] text-[#717B8C] uppercase mb-1">FORWARD TOP SPEED</div>                <div className="text-2xl font-light text-black">8.3 KM/H</div>                <div className="text-[9px] text-[#8C94A4] mt-1">Dual BLDC peak vector</div>              </div>              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="text-[10px] text-[#717B8C] uppercase mb-1">WATERLINE DRAFT</div>                <div className="text-2xl font-light text-black">150 MM</div>                <div className="text-[9px] text-[#8C94A4] mt-1">Ultra-shallow obstacle clearance</div>              </div>              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="text-[10px] text-[#717B8C] uppercase mb-1">SONAR ECHO RANGE</div>                <div className="text-2xl font-light text-black">4.0 METERS</div>                <div className="text-[9px] text-[#8C94A4] mt-1">HC-SR04 acoustic obstacle cone</div>              </div>              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="text-[10px] text-[#717B8C] uppercase mb-1">RF CONTROL DISTANCE</div>                <div className="text-2xl font-light text-black">400 METERS</div>                <div className="text-[9px] text-[#8C94A4] mt-1">HotRC 2.4GHz FHSS Link</div>              </div>              <div className="border border-[#CBD0D9] bg-white p-4">                <div className="text-[10px] text-[#717B8C] uppercase mb-1">CAMERA FIELD OF VIEW</div>                <div className="text-2xl font-light text-black">180° PAN</div>                <div className="text-[9px] text-[#8C94A4] mt-1">SG90 2-Axis PTZ Bracket</div>              </div>            </div>          </div>        </div>      </section>      {/* ─── FULLSCREEN LIGHTBOX MODAL FOR EXPLODED BLUEPRINT ─── */}      {isLightboxOpen && (        <div           className="fixed inset-0 z-50 bg-[#11141D]/90 backdrop-blur-sm flex flex-col items-center justify-center p-4 sm:p-8 animate-in fade-in duration-200"          onClick={() => setIsLightboxOpen(false)}        >          <div             className="relative bg-white max-w-5xl w-full max-h-[90vh] flex flex-col border border-[#CBD0D9] shadow-2xl p-4 sm:p-6"            onClick={(e) => e.stopPropagation()}          >            {/* Modal Header */}            <div className="flex items-center justify-between border-b border-[#CBD0D9] pb-3 mb-4 font-mono text-xs">              <div>                <span className="font-bold text-black uppercase tracking-wider">                  FLOODSCOUT MK-II // EXPLODED ENGINEERING SCHEMATIC                </span>                <span className="block text-[10px] text-[#717B8C] mt-0.5">                  DWG NO. UTM-FS-2026-EXP-01 • ALL 22 HARDWARE SUBSYSTEMS MAPPED                </span>              </div>              <button                onClick={() => setIsLightboxOpen(false)}                className="p-1.5 hover:bg-neutral-200 text-black transition-colors rounded cursor-pointer"                title="Close"              >                <X size={20} />              </button>            </div>            {/* Modal Image */}            <div className="flex-1 overflow-auto flex items-center justify-center bg-[#F9FAFB] p-2 border border-[#E5E7EB]">              <img                src="/image/floodscout-exploded.jpg"                alt="FloodScout Exploded View Large"                className="max-h-[75vh] w-auto object-contain"              />            </div>            {/* Modal Footer Key */}            <div className="flex flex-wrap items-center justify-between gap-2 pt-3 mt-2 border-t border-[#CBD0D9] font-mono text-[10px] text-[#717B8C]">              <span>[01] PTZ VISION • [02] WEATHERPROOF SHELTER • [03] ACOUSTIC SONAR • [04] BLDC THRUSTERS • [05] PVC PONTOONS</span>              <button                onClick={() => setIsLightboxOpen(false)}                className="text-black font-bold uppercase hover:underline"              >                CLOSE SCHEMATIC [ESC]              </button>            </div>          </div>        </div>      )}    </div>  );}